package com.bananalab.lite;
import java.util.regex.*;
/** Verified local explanations and queries over executable scene state. */
final class SceneGuide{
 static String reply(String input,SceneDraft d)throws Exception{String q=CreationRequest.normalize(input);
  if(q.matches("que (?:es|significa) (?:entregar|una entrega)|como funciona la entrega"))return "Entregar cambia quién sostiene un objeto. En Banana, un personaje se acerca, pasa la caja o lámpara al otro y el portador cambia durante ese tiempo.";
  if(q.matches("que significa mientras|que son acciones simultaneas"))return "‘Mientras’ coloca dos acciones en el mismo tiempo: Tony baila mientras entra el pepino. Cada personaje puede hacer una acción en ese tiempo.";
  if(q.matches("que significa despues|como cambio el orden"))return "‘Después’ coloca una acción luego de otra. Podés decir: Tony baila después de que el pepino entra. Si no queda claro qué mover, te lo pregunto.";
  if(q.matches("que (?:es|significa) (?:un )?perfil|que vistas hay|como giro un personaje"))return "El catálogo propio tiene frente, perfil y espalda. El perfil izquierdo refleja el derecho. Podés pedir ‘pone a Tony de perfil’. No puedo reconstruir la espalda de una imagen importada.";
  if(q.matches("como mantengo el mismo personaje|como conservo el diseno"))return "Creá un personaje con nombre y reutilizalo. Por ejemplo: ‘crea a Tony una banana detective’. Las acciones conservan su diseño; ‘mis personajes’ permite recuperar diseños guardados.";
  if(q.matches("como reviso el resultado|como compruebo la escena|como se cuando terminaste"))return "Pedime ‘mostrame el plan’ para revisar personajes, acciones y tiempos. El plan validado comprueba su estructura; después mirá la animación para comprobar la apariencia y los movimientos.";
  if(q.matches("resumi la escena|resumi el proyecto actual|que estamos haciendo|que estamos creando"))return d==null?"Todavía no hay una escena guardada.":summary(d);
  if(d==null)return null;
  Matcher identity=Pattern.compile("quien es (.+)").matcher(q);if(identity.matches()){SceneDraft.Actor a=ScenePlanner.resolve(d,identity.group(1),false);if(a!=null)return a.display()+" es "+a.kind+" en el proyecto guardado.";if(identity.group(1).matches("(?:ese|esa|el anterior|el de antes|el que .*)"))return "No pude identificar un único personaje con esa referencia. Nombralo para consultar su estado.";}
  if(q.matches("cuanto dura|cuanto dura la escena|cuanto dura el video|cual es la duracion"))return "Esta toma dura "+SceneTiming.seconds(d)+" segundos.";
  Matcher spoken=Pattern.compile("(?:que dice|que va a decir|que frases tiene|que voz tiene) (.+)").matcher(q);if(spoken.matches()){SceneDraft.Actor a=ScenePlanner.resolve(d,spoken.group(1),false);if(a==null)return "Nombrá al personaje para consultar su diálogo o voz.";if(q.startsWith("que voz"))return a.display()+" usa la voz sintética experimental "+a.voice+".";StringBuilder b=new StringBuilder(a.display()+":");int n=0;for(SceneDraft.Line line:d.dialogue)if(line.actor.equals(a.name)){b.append("\nTiempo ").append(line.slot+1).append(": «").append(line.text).append("»");n++;}return n==0?a.display()+" todavía no tiene una frase hablada.":b.toString();}
  Matcher detail=Pattern.compile("(?:como es|que aspecto tiene|que ropa tiene|que hace|que acciones tiene|con quien habla) (.+)").matcher(q);
  if(detail.matches()){SceneDraft.Actor a=ScenePlanner.resolve(d,detail.group(1),false);if(a==null)return "No pude identificar un único personaje; nombralo para consultar el estado guardado.";if(q.startsWith("como es")||q.startsWith("que aspecto")||q.startsWith("que ropa"))return a.display()+" es "+a.kind+". Diseño guardado: "+(a.look.isEmpty()?"aspecto original":a.look)+". Vista: "+a.view+".";StringBuilder answer=new StringBuilder(a.display()+":");int count=0;for(int i=0;i<d.actions.size();i++)if(d.cast.get(d.actors.get(i))==a&&(!q.startsWith("con quien")||d.actions.get(i).equals("habla"))){answer.append("\nTiempo ").append(d.slot(i)+1).append(": ").append(Timeline.label(d.actions.get(i)));SceneDraft.Actor other=d.get(d.recipient(i));if(other!=null)answer.append(" con ").append(other.display());count++;}return count==0?a.display()+" no tiene esa acción asignada.":answer.toString();}
  if(q.matches("continua la historia|segui la historia|continua la escena|segui la escena"))return summary(d)+"\n¿Qué querés que pase después? Nombrá el personaje y la acción para continuar conservando sus diseños.";
  if(q.matches("cuantos personajes hay|quienes estan en la escena")){StringBuilder s=new StringBuilder("Hay ").append(d.cast.size()).append(" personajes:");for(SceneDraft.Actor a:d.cast)s.append(" ").append(a.display()).append(" (").append(a.kind).append(")");return s.toString()+".";}
  if(q.matches("revisa contradicciones|hay contradicciones|revisa la coherencia")){String issue=SceneConsistency.problem(d);return issue==null?"No encontré contradicciones en las acciones y entregas comprobables del plan. Revisá la vista previa para evaluar el movimiento.":"Encontré un problema: "+issue;}
  Matcher event=Pattern.compile("quien recibio (?:primero )?(?:la |el )?(caja|lampara)(?: de (.+))?").matcher(q);if(event.matches()){SceneDraft.Actor source=event.group(2)==null?null:ScenePlanner.resolve(d,event.group(2),false);if(event.group(2)!=null&&source==null)return "Nombrá al emisor de esa entrega.";SceneDraft.Actor a=SceneResolver.received(d,event.group(1),source==null?"":source.name,q.contains("primero"));return a==null?"No encontré una recepción única de ese objeto en el plan.":a.display()+" recibió la "+event.group(1)+" en esa entrega.";}
  Matcher owner=Pattern.compile("quien (?:tiene|sostiene|termina con|recibe) (?:la |el )?(caja|lampara)(?: al final)?").matcher(q);
  if(owner.matches()){for(SceneDraft.Prop p:d.props)if(p.type.equals(owner.group(1))){ObjectTransfer.State state=ObjectTransfer.at(d,p.id,1,ObjectTransfer.beats(d));SceneDraft.Actor a=d.get(state.owner());return a==null?"Al final, ese objeto queda en el escenario sin portador.":"Al final, "+a.display()+" sostiene la "+p.type+".";}return "Ese objeto todavía no está en la escena.";}
  Matcher when=Pattern.compile("cuando (?:entra|aparece|llega) (?:el |la )?(.+)").matcher(q);if(when.matches()){SceneDraft.Actor a=ScenePlanner.resolve(d,when.group(1),false);if(a==null)return "Nombrá al personaje para consultar su entrada.";for(int i=0;i<d.actions.size();i++)if(d.cast.get(d.actors.get(i))==a&&d.actions.get(i).matches("entraizq|entrader"))return a.display()+" entra en el tiempo "+(d.slot(i)+1)+".";return a.display()+" no tiene una entrada asignada; permanece en la escena.";}
  return null;
 }
 static String summary(SceneDraft d){return "Estado guardado del proyecto:\n"+d.describe();}

}
